mapper.select:
SELECT id, workspace_id, knowledge_base_id, display_name, media_type,
       current_version_id, created_at, updated_at
FROM documents
WHERE workspace_id = #{workspaceId}
  AND knowledge_base_id = #{knowledgeBaseId}
  AND id = #{documentId}
FOR UPDATE

mapper.update:
UPDATE documents
SET current_version_id = #{versionId}, updated_at = CURRENT_TIMESTAMP
WHERE workspace_id = #{workspaceId}
  AND id = #{documentId}
  AND EXISTS (
	SELECT 1 FROM document_versions v
	WHERE v.workspace_id = documents.workspace_id
	  AND v.document_id = documents.id
	  AND v.id = #{versionId}
  )
